public class AutomationRuleFactory(string resourceName = null, Action<Humidifier.ComputeOptimizer.AutomationRule> factoryAction = null) : ResourceFactory<Humidifier.ComputeOptimizer.AutomationRule>(resourceName)
{

    internal InnerAutomationRuleScheduleFactory ScheduleFactory { get; set; }

    internal InnerAutomationRuleCriteriaFactory CriteriaFactory { get; set; }

    internal InnerAutomationRuleOrganizationConfigurationFactory OrganizationConfigurationFactory { get; set; }

    protected override Humidifier.ComputeOptimizer.AutomationRule Create()
    {
        var automationRuleResult = CreateAutomationRule();
        factoryAction?.Invoke(automationRuleResult);

        return automationRuleResult;
    }

    private Humidifier.ComputeOptimizer.AutomationRule CreateAutomationRule()
    {
        var automationRuleResult = new Humidifier.ComputeOptimizer.AutomationRule
        {
            GivenName = InputResourceName,
        };

        return automationRuleResult;
    }
    public override void CreateChildren(Humidifier.ComputeOptimizer.AutomationRule result)
    {
        base.CreateChildren(result);

        result.Schedule ??= ScheduleFactory?.Build();
        result.Criteria ??= CriteriaFactory?.Build();
        result.OrganizationConfiguration ??= OrganizationConfigurationFactory?.Build();
    }

} // End Of Class

